package net.moz.driver;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.content.pm.ServiceInfo;import android.database.Cursor;import android.database.sqlite.*;import android.location.*;import android.os.*;import android.webkit.CookieManager;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.*;import java.util.concurrent.*;
public class TrackingService extends Service implements LocationListener {
 private LocationManager manager;private QueueDb db;private ScheduledExecutorService io;private String trip,owner;private volatile boolean verified=false,closing=false;private long lastFix=0;private final String channel="moz_tracking";
 @Override public void onCreate(){super.onCreate();db=new QueueDb(this);manager=(LocationManager)getSystemService(LOCATION_SERVICE);io=Executors.newSingleThreadScheduledExecutor();getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel(channel,"MOZ — Rastreamento de viagem",NotificationManager.IMPORTANCE_LOW));}
 Notification notification(String message){Intent open=new Intent(this,MainActivity.class);PendingIntent p=PendingIntent.getActivity(this,1,open,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Intent stop=new Intent(this,TrackingService.class).setAction("STOP");PendingIntent q=PendingIntent.getService(this,2,stop,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);return new Notification.Builder(this,channel).setContentTitle("MOZ Driver").setContentText(message).setSmallIcon(android.R.drawable.ic_menu_mylocation).setContentIntent(p).setOngoing(true).addAction(new Notification.Action.Builder(android.R.drawable.ic_menu_close_clear_cancel,"Interromper GPS",q).build()).build();}
 void status(String message){getSystemService(NotificationManager.class).notify(101,notification(message));}
 @Override public int onStartCommand(Intent i,int flags,int startId){if(i==null||"STOP".equals(i.getAction())){stopSelf();return START_NOT_STICKY;}String t=i.getStringExtra("trip"),o=i.getStringExtra("owner");try{UUID.fromString(t);UUID.fromString(o);}catch(Exception e){stopSelf();return START_NOT_STICKY;}if(trip!=null){if(!trip.equals(t)||!owner.equals(o))status("Já existe rastreamento ativo. Interrompa-o antes de trocar de viagem.");return START_NOT_STICKY;}trip=t;owner=o;if(Build.VERSION.SDK_INT>=29)startForeground(101,notification("Verificando viagem…"),ServiceInfo.FOREGROUND_SERVICE_TYPE_LOCATION);else startForeground(101,notification("Verificando viagem…"));
 if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){stopSelf();return START_NOT_STICKY;}
 io.execute(()->{try{JSONObject me=request("/me",null);if(!owner.equals(me.optString("id"))||!"driver".equals(me.optString("role"))||!me.optBoolean("identityVerified"))throw new IOException("Sessão inválida");JSONObject current=request("/trips/"+trip,null).getJSONObject("trip");if(current.isNull("started")||!current.isNull("finished"))throw new IOException("Viagem inativa");verified=true;new Handler(Looper.getMainLooper()).post(()->beginGps());io.scheduleWithFixedDelay(this::flush,0,15,TimeUnit.SECONDS);}catch(Exception e){status("Não foi possível validar a viagem. Abra o MOZ e tente novamente.");stopSelf();}});return START_NOT_STICKY;}
 void beginGps(){if(closing)return;try{manager.requestLocationUpdates(LocationManager.GPS_PROVIDER,5000,0,this,Looper.getMainLooper());status("GPS ativo durante a viagem. Pode bloquear a tela.");}catch(SecurityException|IllegalArgumentException e){status("Permissão ou provedor GPS indisponível.");stopSelf();}}
 @Override public void onLocationChanged(Location l){if(!verified||closing||l.getTime()-lastFix<4000)return;lastFix=l.getTime();String id=UUID.randomUUID().toString();try{JSONObject f=new JSONObject();f.put("id",id);f.put("at",Instant.ofEpochMilli(l.getTime()).toString());f.put("lat",l.getLatitude());f.put("lon",l.getLongitude());f.put("accuracy",l.getAccuracy());f.put("speed",l.hasSpeed()?l.getSpeed()*3.6:JSONObject.NULL);io.execute(()->{try{db.insert(id,owner,trip,f.toString());}catch(Exception e){status("Falha no armazenamento local do GPS.");}});}catch(Exception ignored){}}
 @Override public void onProviderDisabled(String p){status("GPS desligado. Ative a localização do aparelho.");}
 @Override public void onProviderEnabled(String p){status("GPS disponível.");}
 @Override public void onStatusChanged(String p,int status,Bundle extras){}
 JSONObject request(String path,JSONArray body)throws Exception{String cookies=CookieManager.getInstance().getCookie(MainActivity.BASE);if(cookies==null||cookies.isEmpty())throw new SecurityException("Sessão expirada");HttpURLConnection c=(HttpURLConnection)new URL(MainActivity.BASE+"/api"+path).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(12000);c.setReadTimeout(15000);c.setRequestProperty("Cookie",cookies);c.setRequestProperty("X-MOZ-Request","1");c.setRequestProperty("Accept","application/json");try{if(body!=null){c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream os=c.getOutputStream()){os.write(body.toString().getBytes(StandardCharsets.UTF_8));}}int code=c.getResponseCode();if(code==401||code==403)throw new SecurityException("Sessão ou vínculo inválido");if(code<200||code>=300)throw new IOException("HTTP "+code);try(InputStream is=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=is.read(b))!=-1)out.write(b,0,n);return new JSONObject(new String(out.toByteArray(),StandardCharsets.UTF_8));}}finally{c.disconnect();}}
 void flush(){if(closing)return;try{JSONObject m=request("/me",null);if(!owner.equals(m.optString("id"))||!"driver".equals(m.optString("role")))throw new SecurityException("Conta diferente");JSONArray batch=db.batch(owner,trip);if(batch.length()==0){JSONObject t=request("/trips/"+trip,null).getJSONObject("trip");if(!t.isNull("finished")){stopSelf();return;}status("GPS ativo · aguardando novas posições");return;}JSONObject r=request("/trips/"+trip+"/fixes",batch);JSONArray ids=r.getJSONArray("acceptedIds");for(int k=0;k<ids.length();k++)db.delete(ids.getString(k),owner,trip);String s=r.optString("status");if("Finalizada".equals(s)||"Cancelada".equals(s)){stopSelf();return;}status("GPS ativo · posições sincronizadas");}catch(SecurityException e){status("Sessão expirada. Acesse novamente o MOZ.");stopSelf();}catch(Exception e){status("Sem comunicação com o servidor. Posições mantidas no aparelho.");}}
 @Override public void onDestroy(){closing=true;if(manager!=null)try{manager.removeUpdates(this);}catch(Exception ignored){}if(io!=null)io.shutdown();stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
 @Override public IBinder onBind(Intent i){return null;}
 static class QueueDb extends SQLiteOpenHelper{QueueDb(Context c){super(c,"moz_gps.db",null,1);}@Override public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE fixes(id TEXT PRIMARY KEY, owner TEXT NOT NULL, trip TEXT NOT NULL, json TEXT NOT NULL)");}@Override public void onUpgrade(SQLiteDatabase db,int a,int b){}void insert(String id,String owner,String trip,String json){ContentValues v=new ContentValues();v.put("id",id);v.put("owner",owner);v.put("trip",trip);v.put("json",json);getWritableDatabase().insertOrThrow("fixes",null,v);}JSONArray batch(String owner,String trip)throws JSONException{JSONArray a=new JSONArray();try(Cursor c=getReadableDatabase().query("fixes",new String[]{"json"},"owner=? AND trip=?",new String[]{owner,trip},null,null,"rowid","50")){while(c.moveToNext())a.put(new JSONObject(c.getString(0)));}return a;}void delete(String id,String owner,String trip){getWritableDatabase().delete("fixes","id=? AND owner=? AND trip=?",new String[]{id,owner,trip});}}
}